CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,full_name VARCHAR(100) NOT NULL,role ENUM('admin','manager','staff') NOT NULL DEFAULT 'staff') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS venues(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,activities VARCHAR(255) NOT NULL DEFAULT '') ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS customers(id INT AUTO_INCREMENT PRIMARY KEY,full_name VARCHAR(120) NOT NULL,email VARCHAR(150) NULL UNIQUE,phone VARCHAR(30) NOT NULL DEFAULT '',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS items(id INT AUTO_INCREMENT PRIMARY KEY,venue_id INT NOT NULL,name VARCHAR(100) NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(venue_id) REFERENCES venues(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transactions(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,venue_id INT NOT NULL,user_id INT NULL,total DECIMAL(12,2) NOT NULL,payment_method VARCHAR(30) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(created_at),INDEX(customer_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(venue_id) REFERENCES venues(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transaction_items(id INT AUTO_INCREMENT PRIMARY KEY,transaction_id INT NOT NULL,item_id INT NOT NULL,qty INT NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(transaction_id) REFERENCES transactions(id) ON DELETE CASCADE,FOREIGN KEY(item_id) REFERENCES items(id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS visits(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT NOT NULL,venue_id INT NOT NULL,activity VARCHAR(50) NOT NULL,duration_min INT NOT NULL DEFAULT 0,check_in DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(check_in),INDEX(customer_id),FOREIGN KEY(customer_id) REFERENCES customers(id),FOREIGN KEY(venue_id) REFERENCES venues(id)) ENGINE=InnoDB;
